<?php declare(strict_types=1); $base=config('app.base_path'); ?><div class="page-header"><div><h1>Fresh Food Coupons</h1><p>Manage business-specific coupons for Fresh Food orders.</p></div><div class="page-actions"><a class="btn btn-primary" href="<?= $base ?>/fresh-food/coupons/create">Add Coupon</a></div></div><div class="card"><table class="table"><thead><tr><th>Business</th><th>Code</th><th>Coupon</th><th>Discount</th><th>Minimum</th><th>Usage</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(empty($coupons)): ?><tr><td colspan="8"><div class="empty-state">No coupons found.</div></td></tr><?php else: foreach($coupons as $c): ?><tr><td><?= htmlspecialchars((string)$c['business_name'],ENT_QUOTES,'UTF-8') ?></td><td><strong><?= htmlspecialchars((string)$c['code'],ENT_QUOTES,'UTF-8') ?></strong></td><td><?= htmlspecialchars((string)$c['name'],ENT_QUOTES,'UTF-8') ?></td><td><?= $c['discount_type']==='PERCENT'?number_format((float)$c['discount_value'],2).'%':'₹'.number_format((float)$c['discount_value'],2) ?><?php if($c['maximum_discount']!==null): ?><small> max ₹<?= number_format((float)$c['maximum_discount'],2) ?></small><?php endif; ?></td><td>₹<?= number_format((float)$c['minimum_order_amount'],2) ?></td><td><?= (int)$c['used_count'] ?><?= $c['usage_limit']===null?' / ∞':' / '.(int)$c['usage_limit'] ?></td><td><?= htmlspecialchars((string)$c['status'],ENT_QUOTES,'UTF-8') ?></td><td><a class="link-button" href="<?= $base ?>/fresh-food/coupons/<?= (int)$c['id'] ?>/edit">Edit</a> <form method="post" action="<?= $base ?>/fresh-food/coupons/<?= (int)$c['id'] ?>/delete" style="display:inline"><button class="link-button" onclick="return confirm('Delete this coupon?')">Delete</button></form></td></tr><?php endforeach; endif; ?></tbody></table></div>
